use vstd::prelude::*;

verus! {
    /// Reverse the elements of `a` in place.
    /// 
    /// After returning,
    ///   1) the length of `a` is unchanged, and
    ///   2) for every index `k < a@.len()`, the new `a@[k]` equals the old `a@[a@.len() - 1 - k]`.
    fn reverse(a: &mut Vec<i32>)
        ensures
            // length unchanged
            a@.len() == old(a@).len(),
            // each element is flipped
            forall |k: nat| k < a@.len() ==>
                a@.index(k) == old(a@).index(a@.len() - 1 - k),
    {
        // Let n be the original length
        let orig_len: nat = a@.len();

        // Two‐pointer indices into the vector,
        // i scans from the left, j from the right (exclusive).
        let mut i: usize = 0;
        let mut j: usize = a.len();
        while i < j
            invariant
                // runtime length matches spec‐length
                a.len() as nat == orig_len,
                // pointers stay in bounds
                (i as nat) <= orig_len,
                (j as nat) <= orig_len,
                // i + j = orig_len, so j = orig_len − i
                (i as nat) + (j as nat) == orig_len,
                // for k < i, a[k] has been reversed
                forall |k: nat| k < (i as nat) ==>
                    a@.index(k) == old(a@).index(orig_len - 1 - k),
                // for k ≥ j, a[k] has been reversed
                forall |k: nat| (j as nat) <= k && k < orig_len ==>
                    a@.index(k) == old(a@).index(orig_len - 1 - k),
                // for i ≤ k < j, a[k] is still the original
                forall |k: nat| (i as nat) <= k && k < (j as nat) ==>
                    a@.index(k) == old(a@).index(k),
            decreases (j - i),
        {
            // move j one step left, then swap the pair
            j = j - 1;
            a.swap(i, j);
            i = i + 1;
        }
    }
}

